macro_rules! BITS_PER_TYPE {
($type:ty) => {
(core::mem::size_of::<$type>() as u64).wrapping_mul(8i32 as $type)
};
}

macro_rules! BIT_MASK {
($nr:expr) => {
UL!() << ($nr) % 64
};
}

macro_rules! BIT_WORD {
($nr:expr) => {
($nr) / 64
};
}

macro_rules! BIT_WORD__2 {
($nr:expr) => {
($nr) / 64
};
}

macro_rules! BIT {
($nr:expr) => {
UL!() << $nr
};
}

macro_rules! BUFFER_TRACE {
() => {
while false {
}
};
}

macro_rules! BUGFLAG_TAINT {
($taint:expr) => {
($taint) << 8i32
};
}

macro_rules! DIV_ROUND_DOWN_ULL {
($ll:expr, $d:expr) => {
{
let mut __v: u64;
let mut __v2: u64 = $ll;
do_div__4!(__v2, $d);
__v = __v2;
__v
}
};
}

macro_rules! DIV_ROUND_UP_ULL {
($ll:expr, $d:expr) => {
DIV_ROUND_DOWN_ULL!((($ll) as u64).wrapping_add(($d) as u64).wrapping_sub(1), $d)
};
}

/// Translate a block number to a cluster number
macro_rules! EXT4_B2C {
($sbi:expr, $blk:expr) => {
($blk) >> unsafe { (*$sbi).s_cluster_bits }
};
}

macro_rules! EXT4_BLOCKS_PER_GROUP {
($s:expr) => {
unsafe { (*EXT4_SB($s)).s_blocks_per_group }
};
}

macro_rules! EXT4_BLOCK_SIZE_BITS {
($s:expr) => {
unsafe { (*$s).s_blocksize_bits }
};
}

macro_rules! EXT4_BLOCK_SIZE {
($s:expr) => {
unsafe { (*$s).s_blocksize }
};
}

/// Translate a cluster number to a block number
macro_rules! EXT4_C2B {
($sbi:expr, $cluster:expr) => {
($cluster) << unsafe { (*$sbi).s_cluster_bits }
};
}

macro_rules! EXT4_CLUSTERS_PER_GROUP {
($s:expr) => {
unsafe { (*EXT4_SB($s)).s_clusters_per_group }
};
}

macro_rules! EXT4_CLUSTER_SIZE {
($s:expr) => {
EXT4_BLOCK_SIZE!($s) << unsafe { (*EXT4_SB($s)).s_cluster_bits }
};
}

macro_rules! EXT4_DESC_PER_BLOCK {
($s:expr) => {
unsafe { (*EXT4_SB($s)).s_desc_per_block }
};
}

macro_rules! EXT4_DESC_SIZE {
($s:expr) => {
unsafe { (*EXT4_SB($s)).s_desc_size }
};
}

macro_rules! EXT4_INODES_PER_GROUP {
($s:expr) => {
unsafe { (*EXT4_SB($s)).s_inodes_per_group }
};
}

macro_rules! EXT4_INODE_SIZE {
($s:expr) => {
unsafe { (*EXT4_SB($s)).s_inode_size }
};
}

macro_rules! EXT4_I {
($inode:expr) => {
{
let mut __v: *mut ext4_inode_info;
__v = ((unsafe { ((($inode) as *mut ()) as *const u8).wrapping_offset(-(offsetof!(ext4_inode_info) as isize)) }) as *mut ()) as *mut ext4_inode_info;
__v
}
};
}

macro_rules! EXT4_JOURNAL {
($inode:expr) => {
unsafe { (*EXT4_SB((*$inode).i_sb)).s_journal }
};
}

/// Translate # of blks to # of clusters
macro_rules! EXT4_NUM_B2C__2 {
($sbi:expr, $blks:expr) => {
$blks.wrapping_add(unsafe { (*$sbi).s_cluster_ratio }).wrapping_sub(1) >> unsafe { (*$sbi).s_cluster_bits }
};
}

/// Amount of blocks needed for quota update - we know that the structure was
/// allocated so we need to update only data block
macro_rules! EXT4_QUOTA_TRANS_BLOCKS {
($sb:expr) => {
if ext4_quota_capable($sb) { 1i32 } else { 0i32 }
};
}

macro_rules! EXT4_SINGLEDATA_TRANS_BLOCKS {
($sb:expr) => {
if ext4_has_feature_extents($sb) { 20u32 } else { 8u32 }
};
}

macro_rules! GENMASK_INPUT_CHECK {
() => {
core::mem::size_of::<__SlateRecord_find_h_67>() as i32
};
}

/// Generate a mask for the specified type @t. Additional checks are made to
