fn ext4_es_status(es: *mut extent_status) -> u32 {
((unsafe { (*es).es_pblk }) >> (core::mem::size_of::<u64>() as u64).wrapping_mul(8).wrapping_sub(5)) as u32
}

fn ext4_es_pblock(es: *mut extent_status) -> u64 {
(unsafe { (*es).es_pblk }) & !(18446744073709551615u64 << (core::mem::size_of::<u64>() as u64).wrapping_mul(8).wrapping_sub(5))
}

fn ext4_es_show_pblock(es: *mut extent_status) -> u64 {
let pblock: u64 = ext4_es_pblock(es);
if pblock == !(18446744073709551615u64 << (core::mem::size_of::<u64>() as u64).wrapping_mul(8).wrapping_sub(5)) { 0 } else { pblock }
}

